INSERT INTO `diendan` (`idd`, `user_id`, `type`, `code`, `title`, `content`, `like`, `view`, `time`, `created_at`) VALUES
(1, 1, 'index', 'nP3aDveXjFE0', 'HoiucNso Đã Chính Thức Mở Test Ngày 29/06/2024\r\n', '        <p><strong>HoiucNso Đã Chính Thức Mở test Beta Ngày 29/06/2024\r\n<p>Sever Chào Đón AE Bằng Bộ 6 Class Với Chiêu Thức 12x Được Làm Lại Gần Như Hoàn Toàn MỚI ( NEW ) Vô Cùng Bắt Mắt. NsoTile Chắc Chắn Là Nơi Chờ Đợi Của Bao Fan Tuổi Thơ .\r\n<p>Đã Open Chính Thức \r\n<p>Sever Hứa Sẽ Mang Lại Nhiều Điều Mới Mẻ Cho Mem Gẵn Bó Lâu Dài\r\n<p>Xu,Lượng Được Đảm Bảo Chặt Chẽ Không Bị Loãng\r\n<p>Admin Và  Key Bạc  Chăm Chỉ Sp Hướng Dẫn AE Mới Và Chưa Hiểu Hết Về Sever )</strong></p>\r\n        \r\n                                    <ul>\r\n                                        <li>\r\n                                          <span style=\"color: rgb(33, 37, 41);\">Group Zalo để giao lưu võ thuật:&nbsp;</span><a href=\"https://zalo.me/g/gtkhwr435\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 102, 204); background-color: transparent;\">https://zalo.me/g/gtkhwr435</a>\r\n                                       </li>\r\n                                    </ul>      \r\n                                 </div>', 'admin', 5, 1689329402, '2024-05-10'),
(2, 1, 'index', 'TgwmQvblP13T', 'Cẩm nang tân thủ cho người mới', '        <p><strong>Không kích hoạt có chơi được game không?</strong></p>\r\n                                    <p>Ko cần kích hoạt ae vẫn có thể chs đc all ko bi hạn chế</p>\r\n                                    <p><br></p>\r\n                                    <p><strong>Tại sao tôi không Xác Thực Tài Khoản được?</strong></p>\r\n                                    <p>Các bạn vào mục tải về, tải lại bản V1.4.8 mới nhất, sau đó vào lại game rồi xác thực là được nhé</p>\r\n                                    <p><br></p>\r\n                                    <p><strong>Làm sao để nhận quà tân thủ?</strong></p>\r\n                                    <p>Khi vào game, anh em lại NPC Admin ở Làng Tone để nhận quà tân thủ, tiếp đó lại NPC Raki để nhập code: quatanthu để nhận thêm một lần nữa, ngoài ra anh em có thể nhận Thưởng Thăng Cấp tại NPC Okanechan mỗi khi đạt một mốc cấp độ nào đó</p>\r\n                                    <p><br></p>\r\n                                    <p><strong>Hiện tại có những CODE gì cho người mới?</strong></p>\r\n                                    <p>Hiện tại game đang trong thời gian test và code luông được update tại <a href=\"/post/02.php\"> bài viết này</a> anh em mới hãy vào cập nhật nhé, để nhận thêm CODE anh em có thể thường xuyên cập nhật code trên <a href=\"/\">diễn đàn</a> hoặc box chat <a href=\"https://zalo.me/g/saourz529\">ZALO</a> nhé!</p>\r\n                                    <p><br></p>\r\n                                    <p><strong>Android nên chơi bản nào để ổn định nhất?</strong></p>\r\n                                    <p>Hiện tại để chơi trên Android ổn định nhất các bạn nên chơi bản Java bằng cách tải J2ME Loader trên CH PLAY, sau đó tải bản Java Auto về và mở J2ME Loader lên để chạy nhé</p>\r\n                                    <p><br></p>\r\n                                    <p><strong>PC nên chơi bản nào để ổn định nhất?</strong></p>\r\n                                    <p>Hiện tại PC các bạn nên chơi giả lập Java là ổn định nhất nhé</p>\r\n                                    <ul>\r\n                                        <li>B1: Tải Microemulator: <a href=\"https://angelchip.net/files/share/AngelChipEmulatorEXE.zip\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 102, 204);\">AngelChipEmulator.zip</a></li>\r\n                                        <li>B2: Tải Game:<span style=\"color: rgb(0, 102, 204);\"> </span><a href=\"/download/Nsokey.jar\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 102, 204);\">nsotile.jar</a> hoặc bạn có thể tải bản khác ở mục TẢI GAME</li>\r\n                                        <li>B3: Giải nén và mở microemulator đã tải về</li>\r\n                                        <li>B4: Kéo bản java vào microemulator và chạy thôi</li>\r\n                                    </ul>\r\n                                    <p><strong>Trên bản IOS tại sao di chuyển lại bị dật lại?</strong></p>\r\n                                    <p>Các bạn chat s6 để giảm tốc độ chạy là được nhé</p>\r\n                                    <p><br></p>\r\n                                    <p><strong>Tại sao nick tôi bị kẹt, đăng nhập không được, hoặc vào Vùng đất ma quỷ bị lag game?</strong></p>\r\n                                    <p>Đối với bản Android và IOS hiện tại đang bị lỗi lag game ở Vùng Đất Ma Quỷ, với Android các bạn có thể chơi bằng J2ME Loader như hướng dẫn bên trên, còn IOS thì sắp tới chúng mình sẽ fix lại nhé ạ</p>\r\n                                    <p><br></p>\r\n                                    <p><strong>Chơi Android không thể gán chiêu, phải làm thế nào?</strong></p>\r\n                                    <p>Tương tự như trên, bản Android cũng đang bị lỗi này, các bạn chơi bằng J2ME Loader như hướng dẫn bên trên để ổn định nhé</p>\r\n                                    <p><br></p>\r\n                                    <p><strong>Tại sao đánh quái không nhận được kinh nghiệm?</strong></p>\r\n                                    <p>Có 2 trường hợp xảy ra:</p>\r\n                                    <ul>\r\n                                        <li>Do bạn đánh quái nằm ngoài khoảng +/-10 level</li>\r\n                                        <li>Do bạn tắt nhận EXP ở NPC Admin</li>\r\n                                    </ul>\r\n                                    <p><strong>Mới chơi GAME, mua bán nick nhưng không biết nên giao dịch thế nào?</strong></p>\r\n                                    <p>Ở mỗi BOX ZALO bên dưới đều sẽ có GIAO DỊCH VIÊN (KEY BẠC), anh em liên hệ những GDV này để làm trung gian tránh lừa đảo khi giao dịch trực tiếp nhé</p>\r\n                                    <p><br></p>\r\n                                    <p><strong>Tại sao sử dụng vật phẩm sự kiện không nhận được EXP?</strong></p>\r\n                                    <p>Hiện tại đang có Tái Lập Đua TOP, anh em tạo tài khoản vào thời gian này sẽ mặc định đưa vào danh sách đua top, các bạn có thể lại NPC ADMIN hủy đua TOP để nhận được EXP khi dùng vật phẩm sự kiện nhé</p>\r\n                                    <p><br></p>\r\n                                    <p><strong style=\"color: rgb(94, 98, 120);\">Tại sao đánh quái không rơi vật phẩm?</strong></p>\r\n                                    <p>Các bạn chỉ đánh quái nằm trong khoảng +/-10 level thôi nhé</p>\r\n                                    <p><br></p>\r\n                                    <p><strong>Nso Key có nhóm cộng đồng nào không?</strong></p>\r\n                                    <p>Có nhaaa:</p>\r\n                                    <ul>\r\n                                        <li><span style=\"color: rgb(33, 37, 41);\">Group Zalo nèee:&nbsp;</span><a href=\"https://zalo.me/g/saourz529\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 102, 204); background-color: transparent;\">https://zalo.me/g/saourz529</a>\r\n                                    </li>\r\n                                    </ul>      \r\n                                </div>', 'admin', 5, 1689345527, '2024-05-10'),
(3, 2, 'index', 'hVjYUG35FEfF', 'GiftCode Khủng', '        <p><strong><h5>GiftCode :  tanthu , hoiucnso\r\n? nhập code tại npc raki ở trường ozaka <3</h5></strong></p>\r\n                                    <p><h6>GiftCode:</h6>.... <small class=\"loading-text\">Loading</small></p>\r\n\r\n                                    <ul>\r\n                                        <li>\r\n                                            <span style=\"color: rgb(33, 37, 41);\">Group Để Giao Lưu:&nbsp;</span><a href=\"https://zalo.me/g/saourz529\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 102, 204); background-color: transparent;\">https://zalo.me/g/saourz529</a>\r\n                                        </li>\r\n                                    </ul>      \r\n                                </div>', 'admin', 7, 1689346273, '2024-05-10'),
(4, 1, 'index', 'Carn5WEUgiqA', 'HoiucNso -   Lôi Đài 69', '        <p><strong><h5>?? Lôi Đài ??\r\n				\r\n<p>⏳️⏳️ Cầu Đăng Kí Tham Gia Tên Nhân Vật Phải Có Đuôi 69 ( ví dụ admin69)\r\n<p><br></p>\r\n<p>♨️ Cấm Chuyển Sinh Thấy Biểu Hiện Chuyển Sinh Band TK Khỏi đấu \r\n<p><br></p>\r\n<p>⏱️ Ngày Thi Đấu Lôi Đài 69 Tối 19h Ngày 10/6/2024 ( chủ nhật )\r\n<p>? Phần Thưởng: Tóp Lôi Đài 69\r\n<p>——————————————————————-\r\n<p>? Phần Quà Cho Các Ninja\r\n<p>?TOP 1: 200k lượng \r\n<p>Hỏa Kì Lân 5* Lv 100 CS víp \r\n<p>Mặt Nạ ss5 tb1 Chỉ Số Hạng Nhất\r\n<p><br></p>\r\n<p>?TOP 2 : 150k lượng\r\n<p>1 Sét Trang Bị Thú Cưỡi Tl9 \r\n<p>Cải trang tb2 Chỉ Số Hạng Nhì\r\n<p><br></p>\r\n<p>?TOP 3 : 100k lượng\r\n<p>1 Bạch Hổ Chọn Chỉ Số ( 3 Sao )\r\n<p>Cải trang tb2 Chỉ Số Hạng Ba\r\n<p><br></p>\r\n<p>?TOP 4-10 : 70k lượng + 3 mặt nạ tb2 vĩnh viễn Tự Mở Chỉ Số Random\r\n<p>—————————————\r\n<p>Lưu ý : - Ngoài ra những ai tham gia nhận. riêng 200k lượng\r\n<p>-chỉ được phép lv.69\r\n<p>-đc phép tinh luyện thức tỉnh và dùng all đồ +16 \r\n<p>-Được Mua Gói Vip5 + Nạp Xu Lượng\r\n<p>-Khi pk không dc tẩy j ngoài dame ( thắng thua do số phận )\r\n<p>————————————\r\n<a class=\"loading-text\">Loading</a></h5></strong></p>\r\n                                   <p><h6>GiftCode:</h6> tanthu , hoiucnso\r\n? nhập code tại npc raki ở trường ozaka <small class=\"loading-text\">Loading</small></p>\r\n\r\n                                    <ul>\r\n                                        <li>\r\n                                            <span style=\"color: rgb(33, 37, 41);\">Group Để Giao Lưu:&nbsp;</span><a href=\"https://zalo.me/g/saourz529\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 102, 204); background-color: transparent;\">https://zalo.me/g/saourz529</a>\r\n                                        </li>\r\n                                    </ul>      \r\n                                </div>', 'admin', 4, 1689353766, '2024-05-15');
