INSERT INTO `news_posts` (`id`, `user_id`, `category_id`, `slug`, `title`, `short_content`, `content`, `thumbnail`, `views`, `status`, `created_at`, `updated_at`) VALUES
(1, 1, 1, '1', 'Sever Cày Chay Đổi Đồ Vip', 'Sever Cày Chay Đổi Đồ Vip', '<div class=\"post-date\">21:36:02 10/07/2024</div>\r\n<div class=\"post-content\">\r\n  <p><strong>Đổi Đồ ở đâu ?</strong></p>\r\n  <p>\r\n    Các bạn đi up ở những map như làng cổ , làng truyền thuyết, map vip, sẽ rớt những vật phẩm dùng để đổi đồ vip.\r\n		Các bạn hãy mang vật phẩm đó qua các npc đổi đồ ở Làng Tone và trao đổi , hoặc sử dụng trực tiếp để nhận đồ.\r\n  </p>\r\n  <p><br /></p>\r\n  <p><strong>Sever có up được xu , lượng không  ?</strong></p>\r\n  <p>\r\n    Có nhé sever dành cho những ae dân cày cuốc , xu lượng sẽ rớt khi các bạn đánh quái ở tất cả các map trừ map thường.\r\n  </p>\r\n  <p><br /></p>\r\n  <p><strong>Làm sao để nhận quà tân thủ?</strong></p>\r\n  <p>\r\n    Khi vào game, anh em lại NPC Admin ở Làng Tone để nhận quà tân thủ, tiếp đó\r\n    lại NPC Okanechan để nhập code . Code sẽ update ở trên web và box zalo bạn vui lòng để ý và xem các thông báo mới, ngoài ra\r\n    anh em có thể nhận Thưởng Thăng Cấp tại NPC Okanechan mỗi khi đạt một mốc\r\n    cấp độ nào đó\r\n  </p>\r\n  <p><br /></p>\r\n  <p><strong>Hiện tại có những gì cho người mới?</strong></p>\r\n  <p>\r\n    Hiện tại đang có code là <strong>tanthu , duatop</strong> cho những anh em mới\r\n    chơi nhé, để nhận thêm CODE anh em có thể tham gia các hoạt động trên\r\n    Box, chúng mình thường xuyên tổ chức để phát code cho người chơi nè\r\n  </p>\r\n  <p><br /></p>\r\n  <p><strong>Android nên chơi bản nào để ổn định nhất?</strong></p>\r\n  <p>\r\n    Hiện tại để chơi trên Android ổn định nhất các bạn nên chơi bản Java bằng\r\n    cách tải J2ME Loader trên CH PLAY, sau đó tải bản Java Auto về và mở J2ME\r\n    Loader lên để chạy nhé\r\n  </p>\r\n  <p><br /></p>\r\n  <p><strong>PC nên chơi bản nào để ổn định nhất?</strong></p>\r\n  <p>Hiện tại PC các bạn nên chơi giả lập Java là ổn định nhất nhé</p>\r\n  <ul>\r\n    <li>\r\n      B1: Tải Microemulator:\r\n      <a\r\n        href=\"https://angelchip.net/files/share/AngelChipEmulatorEXE.zip\"\r\n        rel=\"noopener noreferrer\"\r\n        target=\"_blank\"\r\n        style=\"color: rgb(0, 102, 204)\"\r\n        >AngelChipEmulator.zip</a\r\n      >\r\n    </li>\r\n    <li>\r\n      B2: Tải Game:<span style=\"color: rgb(0, 102, 204)\"> </span\r\n      ><a\r\n       href=\"http://hoiucnso.top/download\"\r\n        rel=\"noopener noreferrer\"\r\n        target=\"_blank\"\r\n        style=\"color: rgb(0, 102, 204)\"\r\n        >Tại đây</a\r\n      >\r\n      hoặc bạn có thể tải bản khác ở mục TẢI GAME\r\n    </li>\r\n    <li>B3: Giải nén và mở microemulator đã tải về</li>\r\n    <li>B4: Kéo bản java vào microemulator và chạy thôi</li>\r\n  </ul>\r\n  <p><strong>Trên bản IOS tại sao di chuyển lại bị dật lại?</strong></p>\r\n  <p>Các bạn chat s6 để giảm tốc độ chạy là được nhé</p>\r\n  <p><br /></p>\r\n  <p>\r\n    <strong\r\n      >Tại sao nick tôi bị kẹt, đăng nhập không được, hoặc vào Vùng đất ma quỷ\r\n      bị lag game?</strong\r\n>\r\n  </p>\r\n  <p>\r\n    Đối với bản Android và IOS hiện tại đang bị lỗi lag game ở Vùng Đất Ma Quỷ,\r\n    với Android các bạn có thể chơi bằng J2ME Loader như hướng dẫn bên trên, còn\r\n    IOS thì sắp tới chúng mình sẽ fix lại nhé ạ\r\n  </p>\r\n  <p><br /></p>\r\n  <p><strong>Chơi Android không thể gán chiêu, phải làm thế nào?</strong></p>\r\n  <p>\r\n    Tương tự như trên, bản Android cũng đang bị lỗi này, các bạn chơi bằng J2ME\r\n    Loader như hướng dẫn bên trên để ổn định nhé\r\n  </p>\r\n  <p><br /></p>\r\n  <p><strong>Tại sao đánh quái không nhận được kinh nghiệm?</strong></p>\r\n  <p>Có 2 trường hợp xảy ra:</p>\r\n  <ul>\r\n    <li>Do bạn đánh quái nằm ngoài khoảng +/-10 level</li>\r\n    <li>Do bạn tắt nhận EXP ở NPC Admin</li>\r\n  </ul>\r\n  <p>\r\n    <strong\r\n      >Mới chơi GAME, mua bán nick nhưng không biết nên giao dịch thế\r\n      nào?</strong\r\n    >\r\n  </p>\r\n  <p>\r\n    Ở mỗi BOX ZALO bên dưới đều sẽ có GIAO DỊCH VIÊN (KEY BẠC), anh em liên hệ\r\n    những GDV này để làm trung gian tránh lừa đảo khi giao dịch trực tiếp nhé\r\n  </p>\r\n  <p><br /></p>\r\n  <p><strong>Tại sao sử dụng vật phẩm sự kiện không nhận được EXP?</strong></p>\r\n  <p>\r\n    Hiện tại đang có Tái Lập Đua TOP, anh em tạo tài khoản vào thời gian này sẽ\r\n    mặc định đưa vào danh sách đua top, các bạn có thể lại NPC ADMIN hủy đua TOP\r\n    để nhận được EXP khi dùng vật phẩm sự kiện nhé\r\n  </p>\r\n  <p><br /></p>\r\n  <p>\r\n    <strong style=\"color: rgb(94, 98, 120)\"\r\n      >Tại sao đánh quái không rơi vật phẩm?</strong\r\n    >\r\n  </p>\r\n  <p>Các bạn chỉ đánh quái nằm trong khoảng +/-7 level thôi nhé</p>\r\n  <p><br /></p>\r\n  <p><strong>NsoPro có nhóm cộng đồng nào không?</strong></p>\r\n  <p>Không những có mà là có rất nhiều nha:</p>\r\n  <ul>\r\n    <li>\r\n      Box Discord:\r\n      <a\r\n        Group Zalo :\r\n        <a\r\n          href=\"https://zalo.me/g/saourz529\"\r\n          rel=\"noopener noreferrer\"\r\n          target=\"_blank\"\r\n          >https://zalo.me/g/gtkhwr435</a\r\n        >\r\n\r\n      </li>\r\n  </ul>\r\n</div>\r\n', '', 3146, 0, NULL, NULL),
(2, 1, 1, '2', '[CHỨC NĂNG] Đổi Đồ Vip', '[CHỨC NĂNG] Đổi Đồ VIP', '<div class=\"post-date\">20:36:02 20/07/2024</div>\r\n<div class=\"post-content\">\r\n  <p>☀️ Ninja School Hoiucnso - Server Cày Chay Nhận Lượng Mỗi Ngày Không Nạp Mà Cũng Có Ăn\r\nTặng Lượng Mỗi Ngày Map up xu lg free</p>\r\n  <p>☀️ Server có lever 130</p>\r\n  <p>\r\n    ☀️ Có trang bị 10x , 12x, 125 siêu mới mẻ update liên tục\r\n  </p>\r\n  <p>☀️ Chiêu thức 12x cực kì mới</p>\r\n  <p>☀️ Sever thuộc dạng cày chay nên ae mới vào sẽ có rất nhiều lg và map up xu lượng free để đổi đồ</p>\r\n  <p>\r\n  <p>☀️ Chiến trường HẮC BẠCH GIẢ với những thay đổi cực mới lạ</p>\r\n  <p>\r\n    ☀️ Hoạt động cày Fan cứng nhận Giftcode hàng tháng<p>\r\n  <p>-----------------------------------------------</p>\r\n\r\n  <ul>\r\n    <li>\r\n     🌐 Trang chủ và tải game: \r\n      <a\r\n        href=\" http://hoiucnso.top/\"\r\n        target=\"_blank\"\r\n        style=\"color: rgb(0, 102, 204)\"\r\n        >https:// http://nsotile.pro/</a\r\n      >\r\n    </li>\r\n    <li>\r\n      🔔 Group Facebook : \r\n      ><a\r\n      hoặc bạn có thể tải bản khác ở mục TẢI GAME\r\n      </li>\r\n          <li>🔹 Group Zalo 1 : \r\n	<a\r\n        href=\"https://zalo.me/g/saourz529\"\r\n        rel=\"noopener noreferrer\"\r\n        target=\"_blank\"\r\n        style=\"color: rgb(0, 102, 204)\"\r\n        >https://zalo.me/g/gtkhwr435</a\r\n      >\r\n      \r\n      </li>\r\n  </ul>\r\n  \r\n</div>\r\n', '', 272, 0, NULL, NULL),
(3, 1, 1, '3', '[HƯỚNG DẪN] TỔNG HỢP LỆNH CHÁT TRONG PHIÊN BẢN JAVA', '[HƯỚNG DẪN] TỔNG HỢP LỆNH CHÁT TRONG PHIÊN BẢN JAVA', '<div class=\"post-date\">20:36:02 29/07/2024</div>\r\n<div class=\"post-content\">\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>ts</strong> : tàn sát all quái trong máp</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>tsn</strong> : tàn sát theo nhóm</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>hsx</strong> : Chỉ hồi sinh xa.</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>bux</strong> : Chỉ buff xa.</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>cn</strong> : Thoát nhóm pt nhóm mới.</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>cy</strong> : Xem thông tin yên up được</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>clv</strong> : Xem thông tin lvl up được</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>gm</strong> + mapID : Bay đến map có id mapID ( ví dụ gm1 sẽ đi đến trường Hirosaki )</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>die</strong> : Tự sát (Trong hành trang cần phải ko có khả di lệnh hay lệnh di chuyển nào).</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>addn</strong> : thêm ng chơi vào ds đánh nhóm</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>tsan</strong> : Tàn sát tất cả boss theo nhóm. Nhóm trưởng chat.</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>tsn + lvboss</strong> : Tàn sát boss theo cấp cả nhóm. Nhóm trưởng chat.</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>attn</strong> : Để làm nv Tà Thú cho nhóm trưởng, thành viên k cùng nhiệm vụ vẫn sẽ bay đến đánh cùng</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>buff</strong> : Để bật buff xa.</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\">Chat riêng <strong>mapup</strong> với người khác : để xem vị trí và map hiện tại đang up.</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\">Chat riêng <strong>yenxu</strong> với người khác : để xem yên và lượng</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\">Chat riêng <strong>level&nbsp;</strong>với người khác : để cem level và % lên cấp</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>kts</strong> : Tàn sát full map</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>ktsX</strong> : Tàn sát với khoảng cách X</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>dcvt</strong> : Bật/tắt đánh chuyển vị trí</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>avt</strong> : Thêm vị trí vào danh sách</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>dvt</strong> : Xóa hết vị trí trong danh sách</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>glv</strong> : Giữ level, trên 98% sẽ tự đăng xuất</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>ak&nbsp;</strong>: Bật/tắt tự đánh, chỉ đánh quái</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>cnhat</strong> : Chuyển cách nhặt từ hút vp sang nhặt xa và ngược lại</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>xX&nbsp;</strong>: Chọn khoảng cách nhặt xa là X, ví dụ chát x150 tầm nhặt xa sẽ là 150, chat x0 sẽ nhặt full map</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>ruong</strong> : Mở hành trang</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>vpnhat</strong> : Mở xem ds vp nhặt</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>sX</strong> : Hack giày tốc độ X</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>rs</strong> : Reset giày về mặc định</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>bang/fz</strong> : Đóng băng</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>pbang/wz</strong> : Phá đóng băng</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>u</strong> : Kinh kông</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>d</strong> : Độn thổ</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>l</strong> : Dịch trái</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>r</strong> : Dịch phải</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>nX</strong> : Chỉnh tầm đánh ngang X</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>cX</strong> : Chỉnh tầm đánh cao X</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>mX&nbsp;</strong>: Chỉnh đánh lan X</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>rsk</strong> : Reset tầm và lan</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>tsX</strong> : Tàn sát boss với level lvboss số X</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>tsa</strong> : Tàn sát all</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>anv</strong> : Auto nvhn</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>att</strong> : Auto tà thú</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>e&nbsp;</strong>: End auto</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>kX</strong> : Chuyển khu X</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>ltd</strong> : Lưu tọa độ khi ở làng or trường</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>nmX</strong> : Next map số X (vd ở làng tone nm0 là next đến ichidai, nm1 next đồi kokoro)</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>npcX</strong> : Act npc id số X (vd npc0 là katana, npc3 là kikiro, npc4 là tabemono, npc5 là kamakura, npc6 là kenshinto,..)</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>hs</strong> : Go to hirosaki</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>hr</strong> : Go to haruna</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>oz</strong> : Go to Oozaka</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>kj</strong> : Go to Kojin</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>sz</strong> : Go to Sanzu</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>tn&nbsp;</strong>: Go to Tone</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>lc&nbsp;</strong>: Go to làng chài</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>ck</strong> : Go to chakumi</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>eg&nbsp;</strong>: Go to echigo</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>os</strong> : Go to oshin</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>mnv</strong> : Đến map làm nv chính</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>mnvp</strong> : Đến map làm nv hàng ngày</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>add</strong> : Thêm item đang chỉ vào ds nhặt</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>del</strong> : Xóa item đang chỉ khỏi ds nhặt</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>aitX</strong> : Thêm item vs id số X</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>ditX</strong> : Xóa item vs id số X</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>dt</strong> : auto làm nhiệm vụ dẫn trẻ ( ra map có jaian chát dt )</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>tb</strong> : auto tìm boss trong map ( đến map xuất hiện boss chát tb )</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>pk</strong> : để bật tắt auto bem những ai bật pk đến gần mình</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>apk tennhatvat</strong> : để thêm người đó vào danh sách pk</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>dpk tennhanvat</strong> : để xóa người đó ra khỏi danh sách pk</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><br></p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>Muốn lật hình auto</strong> trước tiên vào lật tay 1 lần, sau đó mới có thể sài được auto lật hình, cài tốc độ lật về 1 để auto lật nhanh nhất</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>Lỗi bị xóa hết đá trong hành trang&nbsp;</strong>vào MenuAuto chọn tự động, tích vào ô Nhặt N.Liệu (Đá) LV: 7 là sẽ giữ lại đá 7 trở lên, đá 6 trở xuống sẽ xóa hết, muốn giữ lại đá nào thì tự cài</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>Lỗi bị xóa hết trang bị trong hành trang</strong> vào MenuAuto chọn tự động, tích vào ô Nhặt Trang Bị LV: 50 là sẽ giữ lại những trang bị 5x trở lên, các trang bị 1234x sẽ bị xóa</p>\r\n<p style=\"text-align: start;color: rgb(33, 37, 41);background-color: rgb(255, 243, 205);font-size: 14px;\"><strong>Không nên cài auto luyện đá</strong> nếu cố tình cài thì trong khi up sẽ rất gây ra lỗi goback không thể di chuyển lại map đang up</p></div>', '', 219, 0, NULL, NULL);
